    ('cpl_contrato_ligacao', 'write_usize(read_usize(G_STAFF_STATE_TABLE).wrapping_add(read_usize(person).wrapping_mul(0x4f)), i as usize); // the person points to the slot', '// mutacao: a pessoa nao aponta a vaga', 'cpl_4 person contract'),
